$ErrorActionPreference = "Stop"

function Fail([string]$Message) {
  Write-Host "ERROR: $Message" -ForegroundColor Red
  exit 1
}

Write-Host "Travel Log restore patch" -ForegroundColor Cyan
Write-Host "Project root: $(Get-Location)"

if (-not (Test-Path ".git")) {
  Fail "Run this script from the Git project root (the folder that contains .git, static, app, and docker-compose.yml)."
}
if (-not (Test-Path "static")) {
  Fail "static folder was not found."
}
if (-not (Test-Path "static/index.html")) {
  Fail "static/index.html was not found."
}

$addB64 = ""
$addBytes = [Convert]::FromBase64String($addB64)
[IO.File]::WriteAllBytes((Join-Path (Get-Location) "static/add.html"), $addBytes)
Write-Host "OK: created static/add.html (music post screen)" -ForegroundColor Green

$commits = @(git rev-list --all -- "static/index.html")
if ($LASTEXITCODE -ne 0 -or $commits.Count -eq 0) {
  Fail "No Git history for static/index.html was found. Your current music screen is safe in static/add.html."
}

$temp = "static/index.restore.tmp.html"
$found = $false
$foundCommit = ""

foreach ($commit in $commits) {
  $spec = "${commit}:static/index.html"
  cmd /c "git show $spec > $temp" | Out-Null
  if ($LASTEXITCODE -ne 0 -or -not (Test-Path $temp)) { continue }
  $candidate = Get-Content $temp -Raw -Encoding UTF8
  if ($candidate -match "TRAVEL\s*LOG" -or $candidate -match "ARCHIVE OF MOMENTS" -or $candidate -match "FOLLOWING") {
    $found = $true
    $foundCommit = $commit
    break
  }
}

if (-not $found) {
  if (Test-Path $temp) { Remove-Item $temp -Force }
  Fail "The original Travel Log home page was not found in Git history. static/add.html was created, but static/index.html was not changed."
}

Copy-Item "static/index.html" "static/index.before-restore.html" -Force
Move-Item $temp "static/index.html" -Force
Write-Host "OK: restored original home from commit $foundCommit" -ForegroundColor Green

$homeHtml = Get-Content "static/index.html" -Raw -Encoding UTF8

if ($homeHtml -notmatch 'id="muted-home-theme-patch"') {
$themePatch = @'
<style id="muted-home-theme-patch">
:root{--muted-ink:#3f3a40;--muted-soft:#756d73;--muted-lav:#a99ab6;--muted-sage:#9daea3;--muted-rose:#c3a0a4;--muted-paper:rgba(255,252,249,.78);--muted-grad:linear-gradient(135deg,#a99ab6 0%,#9daea3 50%,#c3a0a4 100%)}
html,body{min-height:100%}body{color:var(--muted-ink)!important;background:radial-gradient(circle at 8% 5%,rgba(190,172,193,.44) 0,rgba(190,172,193,0) 32%),radial-gradient(circle at 92% 18%,rgba(168,187,173,.40) 0,rgba(168,187,173,0) 30%),radial-gradient(circle at 70% 90%,rgba(201,166,166,.34) 0,rgba(201,166,166,0) 32%),linear-gradient(145deg,#efeae7 0%,#e9e8e2 50%,#eee6e6 100%)!important;background-attachment:fixed!important}
header,nav,.header,.topbar,.top-bar,.navbar,.nav-bar{background:rgba(255,252,249,.72)!important;backdrop-filter:blur(20px) saturate(115%);-webkit-backdrop-filter:blur(20px) saturate(115%);border-color:rgba(103,91,99,.14)!important}
.card,.post,.post-card,.log-card,.panel,.modal-content,.story,.story-item{background:var(--muted-paper)!important;border-color:rgba(255,255,255,.68)!important;box-shadow:0 18px 55px rgba(84,72,80,.11)!important;backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px)}
button,.btn,[role="button"],input,textarea,select{font:inherit}button,.btn,[role="button"]{transition:transform .16s ease,box-shadow .16s ease,filter .16s ease}button:hover,.btn:hover,[role="button"]:hover{transform:translateY(-1px)}
input,textarea,select{border-color:rgba(111,98,106,.16)!important;background:rgba(255,255,255,.68)!important;color:var(--muted-ink)!important;border-radius:14px!important}
a{color:inherit}.tabs,.tab-list,.filters{border-color:rgba(103,91,99,.14)!important}.tab.active,.tabs .active,[aria-selected="true"]{color:#4e4650!important;border-color:#8f7e92!important}
.avatar,img.avatar,.profile-avatar{box-shadow:0 8px 26px rgba(84,72,80,.12)}
.music-add-entry{background:var(--muted-grad)!important;color:#fff!important;border:0!important;box-shadow:0 12px 30px rgba(112,94,106,.24)!important}.music-add-entry *{color:#fff!important}
</style>
'@
  $homeHtml = $homeHtml -replace '</head>', ($themePatch + "`r`n</head>")
}
if ($homeHtml -notmatch 'id="music-add-route-patch"') {
$routerPatch = @'
<script id="music-add-route-patch">
document.addEventListener("DOMContentLoaded", function () {
  var nodes = Array.prototype.slice.call(document.querySelectorAll("button,a,[role='button']"));
  var addButton = nodes.find(function (el) {
    var text = (el.textContent || "").replace(/\s+/g, " ").trim();
    return /ADD/i.test(text) || el.id === "addButton" || el.id === "add-btn" || el.classList.contains("add-button") || el.classList.contains("add-btn");
  });
  if (!addButton) {
    console.warn("ADD button not found. Open /static/add.html directly.");
    return;
  }
  addButton.classList.add("music-add-entry");
  if (addButton.tagName.toLowerCase() === "a") {
    addButton.setAttribute("href", "/static/add.html");
  }
  addButton.addEventListener("click", function (event) {
    event.preventDefault();
    event.stopImmediatePropagation();
    window.location.href = "/static/add.html";
  }, true);
});
</script>
'@
  $homeHtml = $homeHtml -replace '</body>', ($routerPatch + "`r`n</body>")
  [IO.File]::WriteAllText((Join-Path (Get-Location) "static/index.html"), $homeHtml, [Text.UTF8Encoding]::new($false))
}

Write-Host "" 
Write-Host "DONE" -ForegroundColor Green
Write-Host "Home: http://localhost:8000"
Write-Host "Add screen: http://localhost:8000/static/add.html"
Write-Host "The original DM/account/follow UI is restored from Git, and + ADD opens the music post screen."

